/**
 * =====================================================
 * SIGNUP PAGE (ULTRA FINAL - EMAIL VERIFY PATCH)
 * 기존 기능 유지
 * 회원가입 후 login 이동 유지
 * 전화번호 인증 UI 제거
 * 이메일 인증번호 발송 API 연결
 * 이메일 인증번호 확인 API 연결
 * 이메일 인증번호 확인 후 회원가입
 * 관리자 회원가입 페이지 최소 추가
 * 관리자 권한/업체 종류 선택 최소 추가
 * =====================================================
 */

function SignupPage({ navigate }) {
  const [form, setForm] = useState({
    id: "",
    password: "",
    passwordConfirm: "",
    nickname: "",
    email: "",
    emailCode: "",
  });

  const [loading, setLoading] = useState(false);
  const [sendingCode, setSendingCode] = useState(false);
  const [error, setError] = useState("");
  const [emailCodeSent, setEmailCodeSent] = useState(false);
  const [adminRole, setAdminRole] = useState("user");
  const [adminServiceType, setAdminServiceType] = useState("massage");

  const isAdminSignup = (() => {
    try {
      return window.location.pathname === "/admin/signup";
    } catch {
      return false;
    }
  })();

  const serviceType = (() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const value = String(params.get("serviceType") || "")
        .trim()
        .toLowerCase();

      return value === "karaoke" ? "karaoke" : "general";
    } catch {
      return "general";
    }
  })();

  const go = (path) => {
    try {
      if (typeof navigate === "function") {
        navigate(path);
      } else {
        window.location.href = path;
      }
    } catch {
      window.location.href = path;
    }
  };

  useEffect(() => {
    setError("");
  }, []);

  const update = (key, value) => {
    setForm((prev) => ({
      ...prev,
      [key]: value,
    }));

    if (key === "email") {
      setEmailCodeSent(false);
    }

    setError("");
  };

  const isValidEmail = (value) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  };

  const validate = () => {
    if (isAdminSignup) {
      if (!form.nickname.trim()) return "닉네임을 입력하세요.";
      if (!form.id.trim()) return "아이디를 입력하세요.";
      if (form.id.trim().length < 4) return "아이디는 4자 이상이어야 합니다.";
      if (!form.password) return "비밀번호를 입력하세요.";
      if (form.password.length < 6) return "비밀번호는 6자 이상이어야 합니다.";
      if (form.password !== form.passwordConfirm) return "비밀번호가 일치하지 않습니다.";
      if (!form.email.trim()) return "이메일을 입력하세요.";

      if (!isValidEmail(form.email.trim())) {
        return "이메일 형식이 올바르지 않습니다.";
      }

      if (!["user", "shop", "admin"].includes(adminRole)) {
        return "권한을 선택하세요.";
      }

      if (
        adminRole === "shop" &&
        !["massage", "karaoke"].includes(adminServiceType)
      ) {
        return "업체 종류를 선택하세요.";
      }

      return "";
    }

    if (!form.id.trim()) return "아이디를 입력하세요.";
    if (form.id.trim().length < 4) return "아이디는 4자 이상이어야 합니다.";
    if (!form.password) return "비밀번호를 입력하세요.";
    if (form.password.length < 6) return "비밀번호는 6자 이상이어야 합니다.";
    if (form.password !== form.passwordConfirm) return "비밀번호가 일치하지 않습니다.";
    if (!form.nickname.trim()) return "닉네임을 입력하세요.";

    if (!form.email.trim()) {
      return "이메일을 입력하세요.";
    }

    if (!isValidEmail(form.email.trim())) {
      return "이메일 형식이 올바르지 않습니다.";
    }

    if (!emailCodeSent) {
      return "이메일 인증번호를 먼저 발송해주세요.";
    }

    if (!form.emailCode.trim()) {
      return "이메일 인증번호를 입력하세요.";
    }

    return "";
  };

  const handleSendEmailCode = async () => {
    const email = form.email.trim();

    if (!email) {
      setError("이메일을 입력하세요.");
      return;
    }

    if (!isValidEmail(email)) {
      setError("이메일 형식이 올바르지 않습니다.");
      return;
    }

    try {
      setSendingCode(true);
      setError("");

      await userApi.sendEmailVerificationCode({
        email,
      });

      setEmailCodeSent(true);

      alert("이메일 인증번호 발송 요청이 완료되었습니다.");
    } catch (e) {
      const message =
        e?.message ||
        e?.msg ||
        e?.error ||
        "이메일 인증번호 발송 실패";

      setEmailCodeSent(false);
      setError(message);
    } finally {
      setSendingCode(false);
    }
  };

  const verifyEmailCodeBeforeSignup = async () => {
    const email = form.email.trim();

    await userApi.verifyEmailVerificationCode({
      email,
      code: form.emailCode.trim(),
    });

    return true;
  };

  const resetAdminSignupForm = () => {
    setForm({
      id: "",
      password: "",
      passwordConfirm: "",
      nickname: "",
      email: "",
      emailCode: "",
    });

    setAdminRole("user");
    setAdminServiceType("massage");
    setEmailCodeSent(false);
  };

  const handleSignup = async () => {
    const msg = validate();

    if (msg) {
      setError(msg);
      return;
    }

    try {
      setLoading(true);
      setError("");

      if (isAdminSignup) {
        const payload = {
          id: form.id.trim(),
          password: form.password,
          nickname: form.nickname.trim(),
          email: form.email.trim(),
          role: adminRole,
          serviceType:
            adminRole === "shop"
              ? adminServiceType
              : "general",
        };

        await userApi.adminRegister(payload);

        alert("회원가입 완료");
        resetAdminSignupForm();
        return;
      }

      await verifyEmailCodeBeforeSignup();

      const payload = {
        id: form.id.trim(),
        password: form.password,
        nickname: form.nickname.trim(),
        email: form.email.trim(),
        serviceType,
      };

      const res = await userApi.register(payload);

      const token = res.token || res.data?.token;
      const user = res.user || res.data?.user;

      if (token) {
        localStorage.setItem("token", token);

        if (user) {
          localStorage.setItem("user", JSON.stringify(user));
        }

        alert("회원가입 완료");
        go("/login");
        return;
      }

      alert("회원가입 완료. 로그인해주세요.");
      go("/login");
    } catch (e) {
      const rawMessage =
        e?.message ||
        e?.msg ||
        e?.error ||
        "회원가입 실패";

      const message =
        rawMessage === "USER_ALREADY_EXISTS"
          ? "이미 사용 중인 아이디입니다. 다른 아이디를 입력하세요."
          : rawMessage === "EMAIL_ALREADY_EXISTS"
          ? "이미 사용 중인 이메일입니다. 다른 이메일을 입력하세요."
          : rawMessage === "ADMIN_REQUIRED"
          ? "관리자 권한이 필요합니다."
          : rawMessage === "INVALID_SERVICE_TYPE"
          ? "업체 종류를 다시 선택하세요."
          : rawMessage === "INVALID_ROLE"
          ? "권한을 다시 선택하세요."
          : rawMessage === "AUTH_TOKEN_REQUIRED"
          ? "관리자 로그인이 필요합니다."
          : rawMessage === "INVALID_ADMIN_TOKEN"
          ? "관리자 로그인 정보가 올바르지 않거나 만료되었습니다."
          : rawMessage;

      setError(message);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSignup();
    }
  };

  if (!isAdminSignup) {
    return (
      <div style={personalContainer}>
        <div style={personalCardSizeGuide}>
          <h2 style={personalTitleStyle}>노라 개인 회원가입</h2>
          <div style={personalTitleLine} />
          <p style={personalSubtitleStyle}>
            특별한 일상이 시작되는 곳, 노라와 함께하세요.
          </p>

          {error && (
            <div style={personalErrorStyle}>
              {error}
            </div>
          )}

          <label style={personalLabelStyle}>
            아이디
            <input
              aria-label="아이디"
              type="text"
              value={form.id}
              onChange={(e) => update("id", e.target.value)}
              onKeyDown={handleKeyDown}
              autoComplete="username"
              style={personalLiveInput}
            />
          </label>

          <label style={personalLabelStyle}>
            비밀번호
            <input
              aria-label="비밀번호"
              type="password"
              value={form.password}
              onChange={(e) => update("password", e.target.value)}
              onKeyDown={handleKeyDown}
              autoComplete="new-password"
              style={personalLiveInput}
            />
          </label>

          <label style={personalLabelStyle}>
            비밀번호 확인
            <input
              aria-label="비밀번호 확인"
              type="password"
              value={form.passwordConfirm}
              onChange={(e) => update("passwordConfirm", e.target.value)}
              onKeyDown={handleKeyDown}
              autoComplete="new-password"
              style={personalLiveInput}
            />
          </label>

          <label style={personalLabelStyle}>
            닉네임
            <input
              aria-label="닉네임"
              type="text"
              value={form.nickname}
              onChange={(e) => update("nickname", e.target.value)}
              onKeyDown={handleKeyDown}
              style={personalLiveInput}
            />
          </label>

          <label style={personalLabelStyle}>
            이메일
            <div style={personalEmailRow}>
              <input
                aria-label="이메일"
                type="email"
                value={form.email}
                onChange={(e) => update("email", e.target.value)}
                onKeyDown={handleKeyDown}
                autoComplete="email"
                placeholder="example@email.com"
                style={{
                  ...personalLiveInput,
                  flex: 1,
                  minWidth: 0,
                }}
              />

              <button
                type="button"
                aria-label="이메일 인증번호 발송"
                title={sendingCode ? "발송중" : "인증번호 발송"}
                onClick={handleSendEmailCode}
                disabled={sendingCode}
                style={{
                  ...personalEmailButton,
                  opacity: sendingCode ? 0.65 : 1,
                  cursor: sendingCode ? "not-allowed" : "pointer",
                }}
              >
                {sendingCode ? "발송중" : "인증번호 발송"}
              </button>
            </div>
          </label>

          <label style={personalLabelStyle}>
            이메일 인증번호
            <input
              aria-label="이메일 인증번호"
              type="text"
              value={form.emailCode}
              onChange={(e) => update("emailCode", e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={
                emailCodeSent
                  ? "이메일 인증번호를 입력하세요"
                  : "이메일 인증번호 발송 후 입력"
              }
              style={personalLiveInput}
            />
          </label>

          <button
            type="button"
            aria-label="회원가입"
            title={loading ? "가입 중..." : "회원가입"}
            disabled={loading}
            onClick={handleSignup}
            style={{
              ...personalPrimaryButton,
              opacity: loading ? 0.65 : 1,
              cursor: loading ? "not-allowed" : "pointer",
            }}
          >
            {loading ? "가입 중..." : "회원가입"}
          </button>

          <button
            type="button"
            aria-label="이미 계정이 있어요"
            title="이미 계정이 있어요"
            onClick={() => go("/login")}
            style={personalSecondaryButton}
          >
            이미 계정이 있어요
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={adminContainer}>
      <div style={adminCard}>
        <h2 style={{ color: "#d4af37" }}>
          회원가입 페이지
        </h2>

        {error && <div style={errorStyle}>{error}</div>}

        {renderInput("닉네임", "nickname")}
        {renderInput("아이디", "id")}
        {renderInput("비밀번호", "password", "password")}
        {renderInput("비밀번호 확인", "passwordConfirm", "password")}

        <label style={labelStyle}>
          이메일
          <input
            type="email"
            value={form.email}
            onChange={(e) => update("email", e.target.value)}
            onKeyDown={handleKeyDown}
            style={input}
            placeholder="example@email.com"
          />
        </label>

        <label style={labelStyle}>
          권한
          <select
            value={adminRole}
            onChange={(e) => {
              const nextRole = e.target.value;
              setAdminRole(nextRole);

              if (nextRole !== "shop") {
                setAdminServiceType("massage");
              }

              setError("");
            }}
            style={input}
          >
            <option value="user">유저</option>
            <option value="shop">업체</option>
            <option value="admin">관리자</option>
          </select>
        </label>

        <label style={labelStyle}>
          업체 종류 목록
          <select
            value={
              adminRole === "shop"
                ? adminServiceType
                : ""
            }
            onChange={(e) => {
              const nextServiceType = e.target.value;

              setAdminServiceType(nextServiceType);

              if (
                nextServiceType === "massage" ||
                nextServiceType === "karaoke"
              ) {
                setAdminRole("shop");
              }

              setError("");
            }}
            style={{
              ...input,
              opacity: 1,
              cursor: "pointer",
            }}
          >
            <option value="">
              업체 권한 선택 시 설정
            </option>
            <option value="massage">마사지</option>
            <option value="karaoke">가라오케</option>
          </select>
        </label>

        <button
          disabled={loading}
          onClick={handleSignup}
          style={{
            ...primaryButton,
            opacity: loading ? 0.6 : 1,
            cursor: loading ? "not-allowed" : "pointer",
          }}
        >
          {loading ? "가입 중..." : "회원가입"}
        </button>
      </div>
    </div>
  );

  function renderInput(label, key, type = "text") {
    return (
      <label style={labelStyle}>
        {label}

        <input
          type={type}
          value={form[key]}
          onChange={(e) => update(key, e.target.value)}
          onKeyDown={handleKeyDown}
          style={input}
        />
      </label>
    );
  }
}

